#!/usr/bin/env python3
"""
Video Editing Utilities using Word-Level Transcript Timestamps.
Provides practical functions to cut clips, remove pauses, search words, and burn subtitles using FFmpeg.
"""

import json
import subprocess
from pathlib import Path
from typing import List, Dict, Any, Optional


def load_transcript(json_path: str) -> Dict[str, Any]:
    """Load the JSON transcript generated by transcribe.py."""
    with open(json_path, "r", encoding="utf-8") as f:
        return json.load(f)


def find_word_occurrences(transcript_data: Dict[str, Any], query: str) -> List[Dict[str, Any]]:
    """Search for a word or phrase in the transcript and return its exact occurrences with timestamps."""
    results = []
    query_lower = query.strip().lower()
    for word_info in transcript_data.get("words", []):
        clean_word = word_info["word"].strip().lower().strip(".,!?;:\"'")
        if clean_word == query_lower:
            results.append(word_info)
    return results


def cut_video_segment(
    input_video: str,
    output_video: str,
    start_seconds: float,
    end_seconds: float,
    accurate: bool = True,
) -> None:
    """
    Cut a specific section of a video based on start and end timestamps in seconds.
    Uses FFmpeg for fast and accurate cutting.
    """
    duration = end_seconds - start_seconds
    if duration <= 0:
        raise ValueError(f"Invalid segment: start={start_seconds}, end={end_seconds}")

    if accurate:
        # Re-encode for frame-accurate cuts
        cmd = [
            "ffmpeg", "-y",
            "-ss", f"{start_seconds:.3f}",
            "-i", input_video,
            "-t", f"{duration:.3f}",
            "-c:v", "libx264", "-c:a", "aac",
            output_video,
        ]
    else:
        # Stream copy (ultra fast, no re-encoding, cuts at nearest keyframe)
        cmd = [
            "ffmpeg", "-y",
            "-ss", f"{start_seconds:.3f}",
            "-i", input_video,
            "-t", f"{duration:.3f}",
            "-c", "copy",
            output_video,
        ]

    print(f"[*] Running: {' '.join(cmd)}")
    subprocess.run(cmd, check=True)
    print(f"[+] Cut saved to: {output_video}")


def create_highlighted_ass_subtitles(
    transcript_data: Dict[str, Any],
    ass_path: str,
    words_per_subtitle: int = 4,
    highlight_color_bgr: str = "&H00FFFF&",  # Yellow in ASS BGR hex
    primary_color_bgr: str = "&HFFFFFF&",    # White
) -> None:
    """
    Creates an Advanced SubStation Alpha (.ass) subtitle file where the active word
    is highlighted as it is spoken (TikTok / Instagram Reels style captioning).
    """
    words = transcript_data.get("words", [])
    if not words:
        print("[!] No words found in transcript.")
        return

    # ASS header with styles
    ass_content = [
        "[Script Info]",
        "ScriptType: v4.00+",
        "PlayResX: 1920",
        "PlayResY: 1080",
        "",
        "[V4+ Styles]",
        "Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding",
        f"Style: Default,Arial,60,{primary_color_bgr},&H000000FF,&H00000000,&H80000000,-1,0,0,0,100,100,0,0,1,3,2,2,40,40,90,1",
        "",
        "[Events]",
        "Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text",
    ]

    def to_ass_time(sec: float) -> str:
        hrs = int(sec // 3600)
        mins = int((sec % 3600) // 60)
        s = int(sec % 60)
        cs = int(round((sec - int(sec)) * 100))
        if cs >= 100:
            cs -= 100
            s += 1
        return f"{hrs}:{mins:02d}:{s:02d}.{cs:02d}"

    # Group words into chunks
    chunks = [words[i:i + words_per_subtitle] for i in range(0, len(words), words_per_subtitle)]

    for chunk in chunks:
        chunk_start = chunk[0]["start"]
        chunk_end = chunk[-1]["end"]

        # For each word in this chunk, show it highlighted during its spoken window
        for active_idx, active_word in enumerate(chunk):
            w_start = to_ass_time(active_word["start"])
            w_end = to_ass_time(active_word["end"])

            # Build line with active word highlighted
            line_parts = []
            for idx, w in enumerate(chunk):
                word_text = w["word"]
                if idx == active_idx:
                    # Highlight color
                    line_parts.append(f"{{\\c{highlight_color_bgr}\\b1}}{word_text}{{\\c{primary_color_bgr}\\b0}}")
                else:
                    line_parts.append(word_text)

            line_text = " ".join(line_parts)
            ass_content.append(f"Dialogue: 0,{w_start},{w_end},Default,,0,0,0,,{line_text}")

    with open(ass_path, "w", encoding="utf-8") as f:
        f.write("\n".join(ass_content) + "\n")
    print(f"[+] Generated animated/highlighted ASS subtitles: {ass_path}")


def burn_subtitles(video_path: str, subtitle_path: str, output_path: str) -> None:
    """Burn subtitles into video using FFmpeg."""
    # FFmpeg requires escaping colons and backslashes in filter paths on Windows
    escaped_sub = str(Path(subtitle_path).resolve()).replace("\\", "/").replace(":", "\\:")
    cmd = [
        "ffmpeg", "-y",
        "-i", video_path,
        "-vf", f"subtitles='{escaped_sub}'",
        "-c:a", "copy",
        output_path,
    ]
    print(f"[*] Burning subtitles: {' '.join(cmd)}")
    subprocess.run(cmd, check=True)
    print(f"[+] Output video saved: {output_path}")


if __name__ == "__main__":
    print("Video Editing Utilities module.")
    print("Example usage in Python:")
    print("  from video_tools import load_transcript, cut_video_segment, create_highlighted_ass_subtitles, burn_subtitles")
    print("  data = load_transcript('my_video_transcript.json')")
    print("  print(f'Total words: {data[\"total_words\"]}')")
